//! /lab/: seeded Omega owns the page structure, the browser client and its run worker
//! (om/lab-page/lab.om and client.om, regenerated by om/lab-page/check.sh).
use maud::{html, Markup, PreEscaped};
pub const TITLE: &str = "Omega Lab: write a kernel, run it in one click | AienOS";
pub const DESCRIPTION: &str = "A data-parallel kernel in Omega beside the same kernel in CUDA C. Run it in your browser as WebAssembly, checked against JavaScript, compile your edit on my DGX Spark, and see every back end and every GPU result that has and has not run.";
pub const URL: &str = "https://www.aienos.com/lab/";
pub const PAGE: &str = include_str!("../../../../om/lab-page/main.html");
pub fn render_lab_page() -> Markup { html! { (PreEscaped(PAGE)) } }
pub fn render_lab_entry() -> Markup {
    html! {
        a href="/lab/" style="display:block;padding:18px 24px;text-align:center;background:var(--bg-base);border-bottom:1px solid var(--border-subtle);color:var(--text-primary);" {
            strong style="color:var(--accent-green);font-family:var(--font-mono);" { "OMEGA LAB" }
            " · Write a kernel, run it in your browser in one click. Nothing to install. "
            span style="text-decoration:underline;text-underline-offset:4px;" { "Open the lab →" }
        }
    }
}
#[cfg(test)]
mod tests {
    use super::*;
    use sha2::{Digest, Sha256};
    #[test]
    fn lab_generated_artifacts_match_hashes() {
        for (bytes, receipt) in [
            (PAGE.as_bytes(), include_str!("../../../../om/lab-page/main.html.sha256")),
            (include_bytes!("../../../../public/js/lab.js").as_slice(), include_str!("../../../../om/lab-page/lab.js.sha256")),
            (include_bytes!("../../../../public/js/lab-worker.js").as_slice(), include_str!("../../../../om/lab-page/lab-worker.js.sha256")),
        ] {
            assert_eq!(format!("{:x}", Sha256::digest(bytes)), receipt.split_whitespace().next().expect("digest"));
        }
        let published = include_str!("../../../../om/lab-page/published.sha256");
        for (bytes, name) in [
            (include_bytes!("../../../../public/lab/axpy.wasm").as_slice(), "axpy.wasm"),
            (include_bytes!("../../../../public/lab/record.tsv").as_slice(), "record.tsv"),
        ] {
            let line = published.lines().find(|l| l.ends_with(name)).expect(name);
            assert_eq!(format!("{:x}", Sha256::digest(bytes)), line.split_whitespace().next().expect("digest"));
        }
    }
    #[test]
    fn lab_keeps_its_evidence_boundaries() {
        for text in ["NOT_RUN", "git clone --depth 1 https://github.com/aien-dev/aienos.com", "sh om/lab-page/run.sh", "id=\"lab-src\"", "ret add mul a x y", "__global__", "PASS"] {
            assert!(PAGE.contains(text), "missing {text}");
        }
        assert!(!PAGE.contains("<script"), "no inline script");
        for (i, _) in PAGE.match_indices(" on") {
            let rest: String = PAGE[i + 3..].chars().take_while(|c| c.is_ascii_alphabetic()).collect();
            assert!(!PAGE[i + 3 + rest.len()..].starts_with('='), "inline handler on{rest}");
        }
        assert!(!PAGE.contains("curl"), "installs go through GitHub only");
        let js = include_str!("../../../../public/js/lab.js");
        let css = include_str!("../../../../public/assets/lab.css");
        for text in [PAGE, js, css] {
            assert!(!text.contains('\u{2014}') && !text.contains('\u{2013}'), "no em or en dash");
        }
        for word in PAGE.split(|c: char| !c.is_ascii_alphabetic()) {
            assert!(!["we", "our", "ours", "ourselves"].contains(&word.to_ascii_lowercase().as_str()), "plural first person: {word}");
        }
        assert!(css.contains("prefers-reduced-motion:no-preference"));
        assert!(!css.contains("http"), "no external assets");
        assert!(css.match_indices('#').all(|(i, _)| css[i + 1..].starts_with("lab-")), "palette tokens only, no hex colors");
    }
}
